import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 46 Can you ...?","description":"学习 can 表能力，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 46 Can you ...?","description":"学习 can 表能力，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 can 表能力，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 45 The boss's letter","link":"/life/english/new-concept/book-1/unit-02/lesson-045"},"next":{"text":"第一册：英语初阶 · Lesson 47 A cup of coffee","link":"/life/english/new-concept/book-1/unit-02/lesson-047"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 45 The boss's letter","link":"/life/english/new-concept/book-1/unit-02/lesson-045"},"next":{"text":"第一册：英语初阶 · Lesson 47 A cup of coffee","link":"/life/english/new-concept/book-1/unit-02/lesson-047"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-02/lesson-046.md","filePath":"life/english/new-concept/book-1/unit-02/lesson-046.md"}`),i={name:"life/english/new-concept/book-1/unit-02/lesson-046.md"};function l(r,e,s,c,d,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-lesson-46-can-you" tabindex="-1">第一册：英语初阶 · Lesson 46 Can you ...? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-46-can-you" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 46 Can you ...?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-02/overview">单元 2</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-045">配套课 Lesson 45</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>说明能够完成的工作 本课要掌握can 表能力，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>type</td><td>/taɪp/</td><td>v.</td><td>打字</td><td>type a report</td></tr><tr><td>letter</td><td>/ˈletə/</td><td>n.</td><td>信</td><td>write a letter</td></tr><tr><td>minute</td><td>/ˈmɪnɪt/</td><td>n.</td><td>分钟</td><td>in a minute</td></tr><tr><td>terrible</td><td>/ˈterəbl/</td><td>adj.</td><td>糟糕的</td><td>a terrible mistake</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>can type — 能够打字</li><li>in a minute — 一会儿；一分钟后</li></ul><h2 id="语法讲解-can-表能力" tabindex="-1">语法讲解：can 表能力 <a class="header-anchor" href="#语法讲解-can-表能力" aria-label="Permalink to &quot;语法讲解：can 表能力&quot;">​</a></h2><p>can 后接动词原形，对所有人称保持 can，不增加 s。否定为 cannot 或 can&#39;t；问句把 can 放在主语前，不另加 do。can 表能力时说明能否完成动作，不等于动作正在发生。副词可说明做得怎样，如 type quickly；形容词常用于描述人或物。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Can you print the report today?</p></blockquote><p>你今天能打印报告吗？</p><p>Can 前置形成问句，you 为主语，print 为原形；today 说明希望完成任务的时间。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>can 后不能加 to，也不能用第三人称形式 translates。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“Can you print the report today?”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Can you print the report today? My colleague can translate this message.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“说明能够完成的工作”写两至三句，再读给同伴听。至少使用一次can 表能力，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Can 前置形成问句，you 为主语，print 为原形；today 说明希望完成任务的时间。 My colleague 是第三人称单数，但 can 不加 s；translate 用原形，this message 为宾语。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>将 You can print it. 改为一般疑问句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Can you print it?</p><p><strong>解析：</strong> 按本课规则判断：can 后接动词原形，对所有人称保持 can，不增加 s。否定为 cannot 或 can&#39;t；问句把 can 放在主语前，不另加 do。can 表能力时说明能否完成动作，不等于动作正在发生。副词可说明做得怎样，如 type quickly；形容词常用于描述人或物。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“你今天能打印报告吗？”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Can you print the report today?</p><p><strong>解析：</strong> Can 前置形成问句，you 为主语，print 为原形；today 说明希望完成任务的时间。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：My colleague can translate this message.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 我的同事能翻译这条信息。</p><p><strong>解析：</strong> My colleague 是第三人称单数，但 can 不加 s；translate 用原形，this message 为宾语。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：can 表能力。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-045">上一课</a> · <a href="/life/english/new-concept/book-1/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-047">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
